    return np.asarray(man.to_mesh().vert_properties, dtype=np.float64)[:, :3]


def bbox_overlap(a, b, pad=0.0):
    A, B = a.bounding_box(), b.bounding_box()
    return all(A[i] - pad < B[i + 3] and B[i] - pad < A[i + 3] for i in range(3))


