        if not isinstance(lst, list) or not lst:
            raise Bad("%s: needs a non-empty list of part names" % where)
        for n in lst:
            if not isinstance(n, str) or not NAME.match(n):
                raise Bad("%s: bad part name %r" % (where, n))
